// Pointer gestures affect the installation, never the visitor's eye height.
export function archiveWheelAction(event,withinMap){
  if(event.ctrlKey)return withinMap?'zoom':'browser';
  return event.metaKey?'browser':'look';
}

export function museumWheelLookY(event) {
  const distance = Math.abs(event.deltaY);
  const detent = [100, 120].some(step => distance >= step * .8
    && Math.abs(distance / step - Math.round(distance / step)) < .01);
  const mouseWheel = event.deltaMode !== 0
    || (Math.abs(event.deltaX) < .01 && detent);
  return mouseWheel ? -event.deltaY : event.deltaY;
}

export function createArchiveGesture({rotate,zoom,look,select,interact}) {
  const pointers=new Map();let dragged=false,pair=null,mode=null,pending=false;
  const measure=()=>{const [a,b]=[...pointers.values()];return a&&b?{distance:Math.hypot(a.x-b.x,a.y-b.y),x:(a.x+b.x)/2,y:(a.y+b.y)/2}:null;};
  function flush(){
    if(!pending||pointers.size<2)return;pending=false;
    const current=measure();
    if(!pair){pair=current;return;}
    const dx=current.x-pair.x,dy=current.y-pair.y,spread=Math.abs(current.distance-pair.distance),travel=Math.hypot(dx,dy);
    if(!mode){
      if(spread<8&&travel<5)return;
      mode=spread>travel*1.6?'pinch':'pan';
    }
    if(mode==='pinch'&&pair.distance>0&&current.distance>0)zoom(current.distance/pair.distance);
    else if(mode==='pan')look?.(dx,dy);
    pair=current;
  }
  return {
    get active(){return pointers.size>0;},
    down(event){if(!pointers.size)dragged=false;pointers.set(event.pointerId,{x:event.clientX,y:event.clientY,startX:event.clientX,startY:event.clientY});if(pointers.size>1){dragged=true;pair=measure();mode=null;pending=false;}interact?.();},
    move(event){
      const point=pointers.get(event.pointerId);if(!point)return;
      const dx=event.clientX-point.x,dy=event.clientY-point.y;
      point.x=event.clientX;point.y=event.clientY;
      // Coalesce both fingers before reading distance. Sequential pointer
      // events otherwise turn an ordinary two-finger pan into a brief zoom.
      if(pointers.size>1){pending=true;interact?.();return;}
      if(Math.hypot(point.x-point.startX,point.y-point.startY)>5)dragged=true;
      if(dragged)rotate(dx,dy);
    },
    flush,
    up(event){if(!pointers.has(event.pointerId))return;flush();pointers.delete(event.pointerId);if(!pointers.size&&!dragged)select(event);if(pointers.size)dragged=true;pair=measure();mode=null;pending=false;},
    cancel(){pointers.clear();dragged=false;pair=null;mode=null;pending=false;},
  };
}
